'use strict';

var _ = require('lodash');

var API = {};

API.check = require('./check');

API.get = function (name) {
    var api = _.get(this, name);
    return api;
};

/**
 * Exports the APIs
 * @type {Object}
 */
module.exports = API;

'use strict';

var async = require('async');
var path = require('path');
var utils = require('../lib/utils');
var Promise = require('../lib/promise');
var APIError = require('../lib/apirequest-error');


// Declare our main module scope
var API;


/**
 * Check Email
 *
 * @param  {object} params - Parameters for request
 * @param  {callback} callback - The callback that handles the response.
 * @return {object} Result
 */
API = function (params, callback, options) {


    options = utils.defaults({}, options, this.options, {
            service: API.SERVICE_NAME,
            method: API.SERVICE_METHOD
        }
    );


    // Declare the promise we will use to wrap the request call
    var promise = new Promise(function (resolve, reject) {

        // Input Validation (we only do the most basic, and let the server do the most so validation will always be up to date)
        if (!params) {
            return reject(new APIError.MissingArgumentError(API.SERVICE_NAME, 'params'));
        }
        else if (!utils.has(params, API.PARAM_EMAIL)) {
            return reject(new APIError.MissingArgumentError(API.SERVICE_NAME, 'params.' + API.PARAM_EMAIL));
        }

        // Prepare Parameters and prepare it for the Request modus
        var query = {
            options: options,
            params: {
                json: true,
                qs: params
            }
        };


        var APIRequest = require('../lib/apirequest');
        APIRequest.request(query, function (err, result) {

            if (utils.isNull(err) && utils.has(result, 'error')) {
                err = utils.get(result, 'error');
            }

            // If an error happens, we return early
            if (err) {
                return reject(err);
            }

            return resolve(result);
        });
    });


    // Ensure callback is set to make the main functions slightly simpler by avoiding nested conditionals
    callback = callback || utils.noop;

    // We offer callback support in addition to promise style (we know callback is set as we default it in the beginning)
    promise
        .then(function (result) {
            callback(null, result);
        })
        .catch(function (err) {
            callback(err);
        });


    // return the promise to the caller
    return promise;
};


var CheckQuery = function (email) {
    this.email = email;
};
API.CheckQuery = CheckQuery;


API.SERVICE_NAME = 'check';
API.SERVICE_METHOD = 'GET';

API.PARAM_EMAIL = 'email';
API.PARAM_SMTP = 'smtp';
API.PARAM_SMTP_TRUE = 1;
API.PARAM_SMTP_FALSE = 0;
API.PARAM_DID_YOU_MEAN = 'did_you_mean';
API.PARAM_USER = 'user';
API.PARAM_DOMAIN = 'domain';
API.PARAM_FORMAT_VALID = 'format_valid';
API.PARAM_MX_FOUND = 'mx_found';
API.PARAM_SMTP_CHECK = 'smtp_check';
API.PARAM_CATCH_ALL = 'catch_all';
API.PARAM_CATCH_ALL_TRUE = 1;
API.PARAM_CATCH_ALL_FALSE = 0;
API.PARAM_ROLE = 'role';
API.PARAM_DISPOSABLE = 'disposable';
API.PARAM_FREE = 'free';
API.PARAM_SCORE = 'score';


/**
 * Exports the APIs
 * @type {Object}
 */
module.exports = API;

'use strict';

var ResultStatus = {};

ResultStatus.OK = 200;
ResultStatus.NOT_CHANGED = 304;

ResultStatus.BODY_EXPR = 'body';
ResultStatus.BODY_RESULTS_EXPR = 'body.results';
ResultStatus.BODY_SUCCESS_EXPR = 'body.success';
ResultStatus.BODY_ERROR_EXPR = 'body.error';

/**
 * Exports ResultStatus
 * @type {Function}
 */
module.exports = ResultStatus;

'use strict';

var Errors = {};

Errors.MissingArgumentError = function(contextName, argumentName) {
    this.message = 'The following argument is required for the `'+ contextName +'` function: '+ argumentName;
};

Errors.MissingRecommendedArgumentError = function(contextName, argumentName) {
    this.message = 'The following argument is recommended for the `'+ contextName +'` function: '+ argumentName;
};

Errors.NotSupportedArgumentError = function(contextName, argumentName) {
    this.message = 'The following argument is not yet supported for the `'+ contextName +'` function: '+ argumentName;
};

Errors.InvalidArgumentError = function(contextName, argumentName, errorLabel) {
    this.message = 'The '+ argumentName +' argument is invalid for the `'+ contextName +'` function: '+ errorLabel;
};

Errors.APIError = {
    MISSING_ACCESS_KEY: 101,
    INVALID_ACCESS_KEY: 101,
    INVALID_API_FUNCTION: 103,
    USAGE_LIMIT_REACHED: 104,
    HTTPS_ACCESS_RESTRICTED: 105,
    FUNCTION_ACCESS_RESTRICTED: 106,
    INACTIVE_USER: 102,
    QUERY_TEXT_IS_ARRAY: 211,
    QUERY_TEXT_NO_ARRAY: 212,
    TOO_MANY_QUERIES: 221,
    DETECTION_FAILED: 910,
    BATCH_DETECTION_FAILED: 911,
    NO_QUERY_TEXT_PROVIDED: 210,
    '404_NOT_FOUND': 404
};

/**
 * Exports ResultStatus
 * @type {Function}
 */
module.exports = Errors;

'use strict';

var _ = require('lodash');
var Transporter = require('./transporter');
var APIResult = require('./apirequest-result');


var APIRequest = {};


/**
 * Create and send request to the API
 * @param  {object}   parameters Parameters used to form request
 * @param  {Function} callback   Callback when request finished or error found
 * @return {Request}             Returns Request object or null
 */
var requestFn = function (parameters, callback) {

    var url = parameters.options.secure ? 'https' : 'http';
    url += '://';
    url += parameters.options.host;
    url += '/';
    url += parameters.options.context;
    url += '/';
    url += parameters.options.service;
    url += '?' + parameters.options.key_type + '=' + parameters.options.access_key;

    parameters.options.url = url;

    // We need to be able to support using native HTTP since the Live endpoint is causing errors on the 304 which cant be handled by request.js library
    // Refer: https://github.com/request/request/issues/2048

    var transporter = new Transporter(parameters.options);
    transporter.req = transporter.request(parameters.params, function (err, result, response) {

        if (err) {
            return callback(err);
        }
        else if (response.statusCode != APIResult.OK || !result) {
            err = _.get(response, APIResult.BODY_ERROR_EXPR);
            return callback(err, result, response);
        }

        result = result || _.get(result, APIResult.BODY_EXPR) || null;

        return callback(null, result, response);
    });
    return transporter;
};
APIRequest.request = requestFn;


/**
 * Exports APIRequest
 * @type {Function}
 */
module.exports = APIRequest;

var path = require('path');

var APIPath = path.join(__dirname, '../', 'index');
var API = require(APIPath);

// TEST START
var chai = require('chai');
var expect = chai.expect;
var assert = require('assert');

describe('#check()', function () {

    this.timeout(20000);

    var user = 'this.is.a';
    var domain = 'test.io';
    var email = ''+ user +'@'+ domain;

    it('basic', function (done) {

        var api = new API({
            access_key: process.env.ACCESS_KEY
        });

        // Check Query
        var query = {
            email: email
        };

        api.check(query)
            .then(function (result) {

                expect(result).is.not.null;
                expect(result).property(api.check.PARAM_USER).equals(user);
                expect(result).property(api.check.PARAM_DOMAIN).equals(domain);
                expect(result).property(api.check.PARAM_CATCH_ALL).to.be.null;

                done(null, result);
            })
            .catch(function (err) {
                done(err);
            });
    });


    it('basic - w. catch-all', function (done) {

        var api = new API({
            access_key: process.env.ACCESS_KEY
        });

        // Check Query
        var query = {
            email: email,
            catch_all: api.check.PARAM_CATCH_ALL_TRUE
        };

        api.check(query)
            .then(function (result) {

                expect(result).is.not.null;
                expect(result).property(api.check.PARAM_USER).equals(user);
                expect(result).property(api.check.PARAM_DOMAIN).equals(domain);
                expect(result).property(api.check.PARAM_CATCH_ALL).to.be.a('boolean');

                done(null, result);
            })
            .catch(function (err) {
                done(err);
            });
    });


    it('basic - w. catch-all on free account', function (done) {

        var api = new API({
            access_key: process.env.ACCESS_KEY_FREE
        });

        // Check Query
        var query = {
            email: email,
            catch_all: api.check.PARAM_CATCH_ALL_TRUE
        };

        api.check(query)
            .then(function (result) {
                expect(result).is.null;
                done(result);
            })
            .catch(function (err) {
                expect(err).property('code').equals(310);
                done(null, err);
            });
    });
});

'use strict';

var _ = require('lodash');
var utils = require('./lib/utils');

/**
 * A module for interacting with mailboxlayer API
 * @module mailboxlayer
 */

/**
 * mailboxlayer constructor.
 * @param {object} options Options to be passed in
 * @constructor
 */
function API(options) {

    this.options = utils.extend(
        {},
        options,
        {
            host: 'apilayer.net',
            context: 'api',
            key_type: 'access_key',
            secure: false
        }
    );

    /**
     * Load the apis from apis directory
     * This file holds all version information
     * @private
     */
    var apis = require('./api');
    this.addAPIs(apis);
}

/**
 * Add API endpoints to object
 *
 * @param {Array} api Api to be added
 * @private
 */
API.prototype.addAPIs = function (apis) {

    for (var apiName in apis) {

        var API = apis[apiName];
        var api = API.bind(this);
        _.extend(api, API);

        this[apiName] = api;
    }
};

/**
 * Export API
 */
module.exports = API;

